/** Independent funding resource. Value and consideration are separate. External funding and import provenance are merchant-attested; no payment is collected by recording them. Replacement refund lots retain original funding provenance and do not represent new paid funding. */ export type GiftCardLoad = { "consideration_money": (({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }) | (null)); /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** Restrictions tied to original funding, including value restored to replacement cards. A win clears only its own restriction. A loss keeps spending restricted until you create a gift card funding disposition. */ "funding_disputes": Array<GiftCardFundingDispute>; "gift_card_id": string; "gift_card_load_id": string; "idempotency_key": string; /** Pending original cash refunds holding unspent value on this descendant funding lot. Unknown provider outcomes retain these holds. */ "purchase_refund_value_holds"?: Array<GiftCardPurchaseRefundValueHold>; /** Cash refunds and manual payment reversals against this original funding load. Pending refunds reserve their value; confirmed success removes it, and confirmed failure releases the hold. */ "purchase_refunds": Array<GiftCardPurchaseRefundAllocation>; "purchase_restoration"?: GiftCardPurchaseRestoration; "refund_provenance"?: GiftCardRefundProvenance; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refund_transferred_money"?: MoneyValue; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "remaining_money": MoneyValue; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "reversed_money": MoneyValue; "source": GiftCardFundingSource; /** RFC3339 timestamp. Format: date-time. */ "source_created_at": string | null; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "value_money": MoneyValue; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "version": string; };
